247	void TranslateQualifiedNamesMatcher::visit(ASTExpressionList & node, const ASTPtr &, Data & data)
248	{
249	    const auto & tables_with_columns = data.tables;
250	
251	    ASTs old_children;
252	    if (data.processAsterisks())
253	    {
254	        bool has_asterisk = false;
255	        for (const auto & child : node.children)
256	        {
257	            if (child->as<ASTAsterisk>() || child->as<ASTColumnsListMatcher>() || child->as<ASTColumnsRegexpMatcher>())
258	            {
259	                if (tables_with_columns.empty())
260	                    throw Exception(ErrorCodes::LOGICAL_ERROR, "An asterisk cannot be replaced with empty columns.");
261	                has_asterisk = true;
262	            }
263	            else if (const auto * qa = child->as<ASTQualifiedAsterisk>())
264	            {
265	                visit(*qa, child, data); /// check if it's OK before rewrite
266	                has_asterisk = true;
267	            }
268	        }
269	
270	        if (has_asterisk)
271	        {
272	            old_children.swap(node.children);
273	            node.children.reserve(old_children.size());
274	        }
275	    }
276	
277	    for (const auto & child : old_children)
278	    {
279	        ASTs columns;
280	        if (const auto * asterisk = child->as<ASTAsterisk>())
281	        {
282	            bool first_table = true;
283	            for (const auto & table : tables_with_columns)
284	            {
285	                for (const auto * cols : {&table.columns, &table.alias_columns, &table.materialized_columns})
286	                {
287	                    for (const auto & column : *cols)
288	                    {
289	                        if (first_table || !data.join_using_columns.contains(column.name))
290	                        {
291	                            std::string column_name = column.name;
292	                            addIdentifier(columns, table.table, column_name);
293	                        }
294	                    }
295	                }
296	                first_table = false;
297	            }
298	
299	            if (asterisk->transformers)
300	            {
301	                for (const auto & transformer : asterisk->transformers->children)
302	                    IASTColumnsTransformer::transform(transformer, columns);
303	            }
304	        }
305	        else if (auto * asterisk_column_list = child->as<ASTColumnsListMatcher>())
306	        {
307	            for (const auto & ident : asterisk_column_list->column_list->children)
308	                columns.emplace_back(ident->clone());
309	
310	            if (asterisk_column_list->transformers)
311	            {
312	                for (const auto & transformer : asterisk_column_list->transformers->children)
313	                    IASTColumnsTransformer::transform(transformer, columns);
314	            }
315	        }
316	        else if (const auto * asterisk_regexp_pattern = child->as<ASTColumnsRegexpMatcher>())
317	        {
318	            String pattern = asterisk_regexp_pattern->getPattern();
319	            re2::RE2 regexp(pattern, re2::RE2::Quiet);
320	            if (!regexp.ok())
321	                throw Exception(ErrorCodes::CANNOT_COMPILE_REGEXP,
322	                    "COLUMNS pattern {} cannot be compiled: {}", pattern, regexp.error());
323	
324	            bool first_table = true;
325	            for (const auto & table : tables_with_columns)
326	            {
327	                for (const auto & column : table.columns)
328	                {
329	                    if (re2::RE2::PartialMatch(column.name, regexp)
330	                        && (first_table || !data.join_using_columns.contains(column.name)))
331	                    {
332	                        addIdentifier(columns, table.table, column.name);
333	                    }
334	                }
335	                first_table = false;
336	            }
337	
338	            if (asterisk_regexp_pattern->transformers)
339	            {
340	                for (const auto & transformer : asterisk_regexp_pattern->transformers->children)
341	                    IASTColumnsTransformer::transform(transformer, columns);
342	            }
343	        }
344	        else if (const auto * qualified_asterisk = child->as<ASTQualifiedAsterisk>())
345	        {
346	            DatabaseAndTableWithAlias ident_db_and_name(qualified_asterisk->qualifier);
347	
348	            for (const auto & table : tables_with_columns)
349	            {
350	                if (ident_db_and_name.satisfies(table.table, true))
351	                {
352	                    for (const auto & column : table.columns)
353	                        addIdentifier(columns, table.table, column.name);
354	                    break;
355	                }
356	            }
357	
358	            if (qualified_asterisk->transformers)
359	            {
360	                for (const auto & transformer : qualified_asterisk->transformers->children)
361	                    IASTColumnsTransformer::transform(transformer, columns);
362	            }
363	        }
364	        else
365	            columns.emplace_back(child);
366	
367	        node.children.insert(
368	            node.children.end(),
369	            std::make_move_iterator(columns.begin()),
370	            std::make_move_iterator(columns.end()));
371	    }
372	}
